style.css:
/* Background */
body {
  background-color: #0a0a1a !important;
  color: #f2f2f2 !important;
}

/* Links */
a {
  color: #8af2e1 !important;
}
a:hover {
  color: #f2a8d8 !important;
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
  color: #b6a8f2 !important;
}

/* Buttons */
button {
  background-color: #b6a8f2 !important;
  color: #0a0a1a !important;
  border: 1px solid #8af2e1 !important;
}
button:hover {
  background-color: #f2a8d8 !important;
  color: #0a0a1a !important;
}

/* Inputs / Forms */
input, textarea, select {
  background-color: #0a0a1a !important;
  border: 1px solid #8af2e1 !important;
  color: #f2f2f2 !important;
}
